#!/bin/sh
set -e

# Trust the project CA certificate if present (generated by the testbed reference-certgen). The
# gateway runs unprivileged, on a read-only root filesystem where it can, so
# instead of adding the CA to the system store it writes the system roots plus
# the CA to /tmp and points SSL_CERT_FILE there. With no writable /tmp it runs
# on the system roots alone.
if [ -f /certs/ca.crt ] &&
   cat /etc/ssl/certs/ca-certificates.crt /certs/ca.crt > /tmp/ca-certificates.crt 2>/dev/null; then
    export SSL_CERT_FILE=/tmp/ca-certificates.crt
fi

exec "$@"
